void PageHandlerAsyncWaiter::GetInfoBars(
    std::vector<InfoBarEntryPtr>* out_infobars) {
  base::RunLoop loop;
  proxy_->GetInfoBars(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<InfoBarEntryPtr>* out_infobars
,
             std::vector<InfoBarEntryPtr> infobars) {*out_infobars = std::move(infobars);
            loop->Quit();
          },
          &loop,
          out_infobars));
  loop.Run();
}

std::vector<InfoBarEntryPtr> PageHandlerAsyncWaiter::GetInfoBars(
    ) {
  std::vector<InfoBarEntryPtr> async_wait_result;
  GetInfoBars(&async_wait_result);
  return async_wait_result;
}

void PageHandlerAsyncWaiter::PerformInfoBarAction(
    InfoBarType type, InfoBarAction action, bool* out_success) {
  base::RunLoop loop;
  proxy_->PerformInfoBarAction(
      std::move(type),
      std::move(action),
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool PageHandlerAsyncWaiter::PerformInfoBarAction(
    InfoBarType type, InfoBarAction action) {
  bool async_wait_result;
  PerformInfoBarAction(std::move(type),std::move(action),&async_wait_result);
  return async_wait_result;
}




